/* 时空并错 — build-free browser client. The server owns all game rules. */
'use strict';
(() => {
  const $ = (q, root = document) => root.querySelector(q);
  const $$ = (q, root = document) => Array.from(root.querySelectorAll(q));
  const esc = v => String(v ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const clone = v => JSON.parse(JSON.stringify(v));
  const readLocal = key => { try { return localStorage.getItem(key); } catch (_) { return null; } };
  const writeLocal = (key, value) => { try { value == null ? localStorage.removeItem(key) : localStorage.setItem(key, value); } catch (_) {} };
  const S = { token:readLocal('imaginary.token'), user:null, catalog:null, builds:[], rooms:[], selectedBuild:readLocal('imaginary.build'), view:'home', room:null, code:readLocal('imaginary.room'), editor:null, editorDirty:false, budget:null, validationError:'', selectedCard:null, selectedSkill:null, selectedEquipment:null, selectedTarget:'', selection:[], busy:false, polling:false, network:true, cardFilter:'', toastTimer:null, previewTimer:null, createRequest:null, credentialPromise:null, costCard:'', costSelection:[], giveSelection:[], serverOffset:0, libraryQuery:"", librarySeries:"", libraryPage:0, puzzle:null, localTemplates:{skills:[],minds:[]}, editorEpoch:0, previewSequence:0 };
  const colors = {cool:'冷色',warm:'暖色',neutral:'无色'};
  const kinds = {basic:'普通基本牌',event:'普通事件牌',persistent:'延时基本牌',delayed:'延时事件牌',custom:'限定心象牌'};
  const phases = {draw:'抽牌阶段',play:'出牌阶段',discard:'弃牌阶段',response:'等待响应'};
  const rank = n => ({1:'A',11:'J',12:'Q',13:'K'}[n] || n);
  const uid = () => (globalThis.crypto && crypto.randomUUID) ? crypto.randomUUID() : Date.now().toString(36) + Math.random().toString(36).slice(2);
  const allBuilds = () => [...(S.catalog?.presets || []),...S.builds];
  const selectedBuild = () => allBuilds().find(b => b.id === S.selectedBuild) || allBuilds()[0];
  const cardDef = c => c.type === 'custom' ? {name:c.custom?.name || c.name || '限定心象',kind:'custom',description:c.description || describeEffects(c.custom?.effects || c.effects || [])} : (S.catalog?.cards?.[c.type] || c);
  const cardName = c => c.name || cardDef(c).name || c.type;
  const opt = (items, value) => Object.entries(items).map(([key,name]) => `<option value="${esc(key)}"${String(value)===key?' selected':''}>${esc(name)}</option>`).join('');
  const btn = (text, action, cls = 'secondary', attrs = '') => `<button class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
  function toast(message, error = false) { const el=$('#toast'); el.textContent=message; el.className='toast'+(error?' error':'');el.hidden=false;clearTimeout(S.toastTimer);S.toastTimer=setTimeout(()=>el.hidden=true,6500); }
  function setNetwork(ok, text) { S.network=ok;$('#network-status').textContent=text || (ok?'已连接':'连接中断 · 正在重试'); }
  function updateHeader() { $('#identity-name').textContent=S.user?.name || '未登记旅人';$('#avatar-initial').textContent=(S.user?.name || '旅').slice(0,1);$('#room-nav').hidden=!S.room; }
  async function api(action, data = {}, options = {}) {
    const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),15000);
    try { const response=await fetch(`api.php?action=${encodeURIComponent(action)}`,{method:'POST',headers:{'Content-Type':'application/json',...(S.token?{'Authorization':`Bearer ${S.token}`}:{})},body:JSON.stringify(data),signal:controller.signal,cache:'no-store'});
      let body;try{body=await response.json();}catch(_){throw new Error('服务器没有返回有效数据。请核对 PHP 配置与部署目录。');}
      if(!response.ok || !body.ok){const err=new Error(body.error || '操作没有完成');err.status=response.status;throw err;}
      setNetwork(true);return body.data;
    } catch(error){if(error.name==='AbortError')throw new Error('连接超时，请稍后重试。');if(!error.status)setNetwork(false);if(error.status===401 && !options.keepAuth){S.token=null;S.user=null;writeLocal('imaginary.token',null);updateHeader();}throw error;} finally{clearTimeout(timeout);}
  }
  async function ensureSession(){ if(S.user&&S.token)return;if(S.credentialPromise)return S.credentialPromise;S.credentialPromise=(async()=>{const name=($('#modal #guest-name')?.value || $('#guest-name')?.value || readLocal('imaginary.name') || `旅人${Math.floor(1000+Math.random()*9000)}`).trim().slice(0,24);const data=await api('guest',{name});S.token=data.token;S.user=data.user;writeLocal('imaginary.token',S.token);writeLocal('imaginary.name',name);updateHeader();})();try{await S.credentialPromise;}finally{S.credentialPromise=null;} }
  async function refreshMe(options={}){const data=await api('me',{},options);S.user=data.user;S.builds=data.builds||[];S.rooms=data.rooms||[];updateHeader();}
  function useRoom(room){if(S.room?.code===room.code&&room.revision<S.room.revision)return;const changed=!S.room||room.code!==S.room.code||room.revision!==S.room.revision||room.status!==S.room.status;S.room=room;S.code=room.code;if(room.game?.serverTime)S.serverOffset=room.game.serverTime*1000-Date.now();const summary={code:room.code,name:room.name,status:room.status,mode:room.mode,revision:room.revision};S.rooms=[summary,...S.rooms.filter(r=>r.code!==room.code)];writeLocal('imaginary.room',room.code);updateHeader();if(S.view==='room'&&changed)renderRoom();}
  async function run(fn){if(S.busy)return;S.busy=true;document.body.classList.add('is-busy');try{await fn();}catch(error){toast(error.message,true);if(error.status===409&&S.code){try{useRoom(await api('room',{code:S.code}));}catch(_){}}}finally{S.busy=false;document.body.classList.remove('is-busy');}}
  function navigate(view){S.view=view;history.replaceState(null,'','#'+view);$$('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===view));const titles={home:'实验大厅',workshop:'角色工坊',reference:'规则与牌库',library:'角色与拼图库',room:'当前对局'};$('#breadcrumb').innerHTML=`工作台 <span>/</span> ${titles[view] || titles.home}`;render();}
  function render(){if(!S.catalog)return;updateHeader();if(S.view==='workshop')renderWorkshop();else if(S.view==='reference')renderReference();else if(S.view==='library')renderLibrary();else if(S.view==='room'&&S.room)renderRoom();else renderHome();if(S.view==='home')renderHistory();}
  function presetCard(b){const c=b.character;return `<article class="preset-card ${selectedBuild()?.id===b.id?'selected':''}" tabindex="0" role="button" aria-label="选择 ${esc(b.name)}" data-action="select-build" data-id="${esc(b.id)}">${portrait(c,"preset-portrait")}<div class="preset-info"><h3>${esc(c.name)}</h3><div class="subtitle">${esc(c.title)} · ${esc(c.series)}</div><p>${esc(c.skills.map(s=>s.name).join(' / '))} · ${esc(b.name)}</p><span class="color-label ${c.color}">${colors[c.color]}阵营</span><span class="small-text muted"> &nbsp; ${c.hp} 体力</span></div>${selectedBuild()?.id===b.id?'<span class="selected-check">✓ 已选择</span>':''}</article>`;}
  function renderHome(){const selected=selectedBuild();$('#main').innerHTML=`<div class="page-heading"><div><h1>欢迎来到心象实验室。</h1><p>选择一个角色，排列十三张心象，开始一次新的相遇。</p></div><span class="pill">● 内测开放中</span></div>
    <section class="hero"><div class="hero-copy"><span class="eyebrow">BUILD YOUR INNER WORLD</span><h2>你的心象，<br>不止一种<em>可能。</em></h2><p>在冷暖交错的世界里，以精神为锋，以记忆为序。<br>从一副十三张的心象牌组，写下你的角色故事。</p><div class="button-row">${btn('开始练习 <span aria-hidden="true">↗</span>','practice','', 'title="使用当前构筑，与两名机器人进行冷暖对抗"')}${btn('创建私人房间','create-room')}</div></div><div class="hero-art" role="img" aria-label="冷暖交融的心象世界插画"><span class="art-caption">THE WORLD BETWEEN MEMORIES</span></div></section>
    <div class="home-grid"><section><div class="section-heading"><h2>从一个心象开始 <small>CURATED CHARACTERS</small></h2><button class="text-button" data-nav="library">浏览全部 ${S.catalog.presets.length} 位角色 →</button></div><div class="preset-grid">${(S.catalog.presets||[]).filter(b=>String(b.character.art).startsWith('kf3_')).concat((S.catalog.presets||[]).filter(b=>!String(b.character.art).startsWith('kf3_'))).slice(0,6).map(presetCard).join('')}</div>${S.builds.length?`<div class="section-heading" style="margin-top:24px"><h2>我的构筑 <small>YOUR COLLECTION</small></h2></div><div class="preset-grid">${S.builds.map(presetCard).join('')}</div>`:''}<div class="lower-banner"><span aria-hidden="true">◇</span><div><h3>还没有遇见属于你的角色？</h3><p>组合触发、条件与效果积木，创造角色与专属心象。</p></div>${btn('设计我的角色 →','new-build','ghost')}</div></section>
    <aside class="home-aside"><section class="quick-panel"><span class="eyebrow">A SEAT IS WAITING</span><h3>与朋友，一起入局。</h3><p>分享六位房间码，就能邀请朋友加入。<br>也可以让机器人陪你试试新构筑。</p><label>房间邀请码<input id="join-code" maxlength="6" autocomplete="off" placeholder="输入 6 位房间码" aria-label="六位房间邀请码"></label>${btn('加入房间 <span aria-hidden="true">→</span>','join-room','secondary')}<p class="help" style="margin:13px 0 0">当前构筑：${esc(selected?.name || '暂无')}<br>${S.user?'身份已保存在本浏览器，可刷新重连。':'首次游戏会自动登记一个本机旅人身份。'}</p>${!S.user?`<label style="margin-top:10px">你的昵称<input id="guest-name" maxlength="24" placeholder="旅人" value="${esc(readLocal('imaginary.name')||'')}"></label>`:''}</section><div class="rule-shortcut"><span>13</span><div><h4>十三张，依序展开</h4><p>A 到 K 各一张。心象可替代通常抽牌，<br>次序就是你的战术。</p></div></div><div class="rule-shortcut"><span>∞</span><div><h4>留下的牌，改变下一回合</h4><p>延时基本牌次回合成熟。<br>留住资源，也留住翻盘的可能。</p></div></div></aside></div>`;}
  function buildPicker(value=selectedBuild()?.id){return `<select id="build-picker" aria-label="选择出战构筑">${allBuilds().map(b=>`<option value="${esc(b.id)}" ${b.id===value?'selected':''}>${esc(b.name)} · ${esc(b.character.name)}${String(b.id).startsWith('preset_')?'（范例）':''}</option>`).join('')}</select>`;}
  function renderHistory(){if(!S.rooms.length||$('#room-history'))return;const states={lobby:'等待开始',playing:'正在对局',finished:'已结束'};$('#main').insertAdjacentHTML('beforeend',`<section class="panel" id="room-history" style="margin-top:25px"><div class="panel-title"><h2>再续一个故事</h2><span class="small-text muted">我参与的房间</span></div><div class="history-list">${S.rooms.slice(0,12).map(r=>`<div class="history-row"><div><b>${esc(r.name)}</b><small>${esc(r.code)} · ${S.catalog.modes[r.mode]} · ${states[r.status]||r.status}</small></div>${btn(r.status==='finished'?'查看复盘 →':'重新连接 →','reconnect-room','secondary small',`data-id="${esc(r.code)}"`)}</div>`).join('')}</div></section>`);}
  function buildPayload(id){return String(id).startsWith('preset_')?{presetId:id}:{buildId:id};}
  function showModal(title,content,actions=''){const modal=$('#modal');$('#modal-content').innerHTML=`<div class="modal-inner"><div class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="关闭对话框">✕</button></div>${content}${actions?`<div class="modal-actions">${actions}</div>`:''}</div>`;if(!modal.open)modal.showModal();}
  function roomForm(){showModal('留一个座位，等故事开始',`<p>房间最多容纳 6 人。房主选择固定模式，也决定是否接纳自创构筑。</p><div class="form-grid"><label class="span-all">房间名称<input id="room-name" maxlength="40" value="${esc((S.user?.name||'旅人')+'的心象实验')}"></label><label>胜利模式<select id="room-mode">${opt({color:'冷暖对抗',series:'系列对抗'},'color')}</select></label><label>回合时限<select id="room-seconds">${opt({60:'60 秒',120:'120 秒',180:'180 秒'},120)}</select></label><label class="span-all">出战构筑${buildPicker()}</label></div><label class="checkbox-row"><input id="allow-custom" type="checkbox" checked><span>允许通过预算校验的自创构筑</span></label>`,btn('创建房间 →','confirm-create',''));}
  async function createRoom(practice=false){await ensureSession();const pick=practice?selectedBuild()?.id:$('#build-picker').value;const payload={name:practice?'心象练习室':$('#room-name').value,mode:practice?'color':$('#room-mode').value,allowCustom:practice?true:$('#allow-custom').checked,turnSeconds:practice?120:Number($('#room-seconds').value),...buildPayload(pick)};const key=JSON.stringify(payload);if(!S.createRequest||S.createRequest.key!==key)S.createRequest={key,id:uid()};const room=await api('create_room',{...payload,requestId:S.createRequest.id});S.createRequest=null;S.selectedBuild=pick;writeLocal('imaginary.build',pick);useRoom(room);$('#modal').close();navigate('room');if(practice){for(let i=0;i<2;i++)useRoom(await api('add_bot',{code:room.code}));useRoom(await api('start',{code:room.code}));}}
  function skillSentence(s){const triggers=S.catalog.blocks.triggers,conditions=S.catalog.blocks.conditions;const limit=s.limit||1;const converted=s.trigger==='convert'?`将「${S.catalog.blocks.conversions?.from?.[s.conversion?.from]||s.conversion?.from||'手牌'}」作为「${S.catalog.blocks.conversions?.to?.[s.conversion?.to]||s.conversion?.to||'牌'}」使用 / 响应`:describeEffects(s.effects||[]);return `${triggers[s.trigger]||s.trigger}，${conditions[s.condition]||s.condition}；每个全局回合至多 ${limit} 次。弃 ${s.cost?.hand||0} 张手牌、${s.cost?.mind||0} 张心象顶牌；${converted}。`;}
  function describeEffects(effects){return effects.map(e=>`${e.target==='target'?'指定 / 关联角色':'自己'}${S.catalog?.blocks?.effects?.[e.op]||e.op} ${e.amount}${['damage','attack'].includes(e.op)?' 点'+(colors[e.color]||'无色')+'伤害':''}`).join('，');}
  function editorStart(build){if(!build&&!selectedBuild())return;S.editor=clone(build||selectedBuild());delete S.editor.budget;delete S.editor.createdAt;delete S.editor.updatedAt;if(String(S.editor.id||'').startsWith('preset_'))delete S.editor.id;S.editor.rulesVersion=S.catalog.rulesVersion;S.editorEpoch++;S.editorDirty=false;S.budget=null;S.validationError='';navigate('workshop');previewBuild();}
  function field(label,path,value,type='text',extra=''){return `<label>${label}<input type="${type}" data-field="${path}" value="${esc(value)}" ${extra}></label>`;}
  function selectField(label,path,items,value){return `<label>${label}<select data-field="${path}">${opt(items,value)}</select></label>`;}
  function effectEditor(effects,path){return effects.map((e,i)=>{const meta=S.catalog.blocks.effectMeta?.[e.op]||{};const targets=Object.fromEntries((meta.targets||['self','target']).map(t=>[t,t==='self'?'自己':'指定 / 关联角色']));return `<div class="effect-row"><select data-field="${path}.${i}.op" aria-label="效果类型">${opt(S.catalog.blocks.effects,e.op)}</select><select data-field="${path}.${i}.target" aria-label="效果目标">${opt(targets,e.target)}</select><input data-field="${path}.${i}.amount" type="number" min="${meta.min||1}" max="${meta.max||3}" value="${e.amount}" aria-label="效果数值">${['damage','attack'].includes(e.op)?`<select class="effect-color" data-field="${path}.${i}.color" aria-label="伤害颜色">${opt(colors,e.color)}</select>`:'<span class="effect-color effect-hint">'+esc(meta.description||'')+'</span>'}<button class="icon-button" data-action="remove-effect" data-path="${path}" data-index="${i}" aria-label="删除效果" ${effects.length<=1?'disabled':''}>×</button></div>`;}).join('')+`<button class="btn ghost small" data-action="add-effect" data-path="${path}" ${effects.length>=3?'disabled':''}>＋ 添加效果积木</button>`;}
  function skillEditor(s,i){const path=`character.skills.${i}`;const convert=s.trigger==='convert';return `<div class="skill-block"><div class="skill-top"><span class="skill-number">0${i+1}</span><input data-field="${path}.name" maxlength="30" value="${esc(s.name)}" aria-label="技能名称"><button class="icon-button" data-action="remove-skill" data-index="${i}" aria-label="删除技能">×</button></div><div class="template-actions">${btn('从拼图库替换','browse-skills','ghost small',`data-index="${i}"`)}${btn('收藏为拼图','save-skill-template','ghost small',`data-index="${i}"`)}</div><div class="form-grid">${selectField('当 · 触发时机',path+'.trigger',S.catalog.blocks.triggers,s.trigger)}${selectField('若 · 额外条件',path+'.condition',S.catalog.blocks.conditions,s.condition)}${selectField('支付 · 弃手牌',path+'.cost.hand',{0:'0 张',1:'1 张',2:'2 张'},s.cost?.hand||0)}${selectField('支付 · 弃心象顶牌',path+'.cost.mind',{0:'0 张',1:'1 张',2:'2 张'},s.cost?.mind||0)}${selectField('每个全局回合使用上限',path+'.limit',{1:'1 次',2:'2 次'},s.limit||1)}</div>${convert?`<div class="block-label">转换 · 保留实体卡，仅改变本次使用 / 响应</div><div class="form-grid">${selectField('转换素材',path+'.conversion.from',S.catalog.blocks.conversions?.from||{attack:'攻击牌',defense:'防御牌',red:'红色花色牌',black:'黑色花色牌',hand:'任意手牌'},s.conversion?.from)}${selectField('视为使用',path+'.conversion.to',S.catalog.blocks.conversions?.to||{attack_neutral:'无色攻击',defense:'防御'},s.conversion?.to)}</div>`:`<div class="block-label">则 · 依序结算以下效果（最多 3 项）</div>${effectEditor(s.effects||[],path+'.effects')}`}<p class="skill-sentence" data-skill-preview="${i}">${esc(skillSentence(s))}</p></div>`;}
  function deckSlot(d,i){const allowed=S.catalog.mindOptions?.[d.rank]||Object.keys(S.catalog.cards);const cardTypes=Object.fromEntries(allowed.map(id=>[id,S.catalog.cards[id].name]));cardTypes.custom='✧ 自创限定心象牌';return `<div class="deck-slot"><span class="slot-order">${String(i+1).padStart(2,'0')}</span><span class="slot-rank">${rank(d.rank)}</span><select data-field="deck.${i}.type" aria-label="第 ${i+1} 张心象，点数 ${rank(d.rank)}">${opt(cardTypes,d.type)}</select><span class="reorder-buttons"><button data-action="move-slot" data-index="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="上移第 ${i+1} 张心象">▲</button><button data-action="move-slot" data-index="${i}" data-direction="1" ${i===12?'disabled':''} aria-label="下移第 ${i+1} 张心象">▼</button></span>${d.type==='custom'?`<div class="custom-slot"><div class="template-actions">${btn('从同 IP 心象库挑选','browse-minds','ghost small',`data-index="${i}"`)}${btn('收藏为心象拼图','save-mind-template','ghost small',`data-index="${i}"`)}</div><div class="form-grid">${field('限定牌名称',`deck.${i}.custom.name`,d.custom.name)}${field('限定系列',`deck.${i}.custom.series`,d.custom.series)}${field('额外绑定角色 ID（留空即同 IP 共享）',`deck.${i}.custom.characterId`,d.custom.characterId||'','text','maxlength="64"')}<div>${selectField('不符合限定时，视为',`deck.${i}.custom.fallback`,cardTypesWithoutCustom(),d.custom.fallback)}</div></div><div class="block-label">符合系列及可选角色绑定时 · 依序结算</div>${effectEditor(d.custom.effects,`deck.${i}.custom.effects`)}</div>`:`<button class="slot-pick text-button" data-action="browse-minds" data-index="${i}">＋ 换为 IP 心象</button>`}</div>`;}
  function cardTypesWithoutCustom(){return Object.fromEntries(Object.values(S.catalog.cards).map(c=>[c.id,c.name]));}
  function renderWorkshop(){if(!S.editor){editorStart(selectedBuild());return;}const b=S.editor,c=b.character;$('#main').innerHTML=`<div class="page-heading"><div><span class="eyebrow">CHARACTER WORKSHOP</span><h1>为你的心象，赋予形状。</h1><p>从经典技能拼图开始，改写触发、条件与效果，创作自己的角色与 IP 心象。</p></div>${btn('载入范例 ↓','load-example','secondary small')}</div><div class="workshop-layout"><div><section class="panel"><div class="panel-title"><h2>01 / 角色档案</h2><span class="pill">固定规则 · 自由创作</span></div><div class="form-grid">${field('构筑名称','name',b.name,'text','maxlength="48"')}${field('角色名称','character.name',c.name,'text','maxlength="48"')}${field('角色称号','character.title',c.title,'text','maxlength="48"')}${field('所属系列','character.series',c.series,'text','maxlength="48"')}${field('角色 ID（用于额外专属绑定）','character.id',c.id,'text','maxlength="64"')}${selectField('颜色阵营','character.color',colors,c.color)}${selectField('初始体力','character.hp',{4:'4 点',5:'5 点',6:'6 点',7:'7 点'},c.hp)}${selectField('精神耗尽时翻面（仅一次）','character.flipColor',c.color==='neutral'?{'':'无色角色不能翻面'}:c.color==='cool'?{'':'不翻面',warm:'翻为暖色'}:{'':'不翻面',cool:'翻为冷色'},c.flipColor||'')}<div class="art-picker"><span class="field-label">角色立绘</span><div class="art-current">${portrait(c,"portrait-option")}${btn("从立绘库选择","browse-art","secondary small")}</div></div></div><p class="help">系列名称参与系列对抗的阵营判定，也决定限定心象牌是否生效。冷暖翻面会保留既有指示物；无色角色不能翻面。</p></section><section class="panel"><div class="panel-title"><h2>02 / 技能积木</h2><span class="small-text muted">${c.skills.length} / 2 个技能</span></div><p class="help">每项技能可设置每个全局回合的次数上限。自动技能按左侧手牌和心象牌顶支付费用；转换技能可在合法的出牌及响应时使用。</p><div class="template-actions">${btn("浏览经典技能拼图","browse-skills","secondary small",'data-index="-1"')}${btn("我的拼图 / 分享","local-templates","ghost small")}</div>${c.skills.map(skillEditor).join('')}${btn('＋ 添加一个技能','add-skill','secondary small',c.skills.length>=2?'disabled':'')}</section><section class="panel"><div class="panel-title"><h2>03 / 十三张心象</h2><span class="small-text muted">${b.deck.filter(d=>d.type==='custom').length} / 4 张限定牌</span></div><p class="help">点数 A～K 各一张。上下移动卡牌来决定抽取次序；限定牌可自选其系列外的普通效果。</p><div class="deck-guide"><span>↓ 牌顶 · 最先抽取</span><span>顺序　点数　牌名</span></div>${b.deck.map(deckSlot).join('')}<div class="deck-guide"><span>牌底 · 最后抽取</span><span>A = 1 · J = 11 · Q = 12 · K = 13</span></div></section><div class="save-bar"><p id="save-state">${S.editorDirty?'有未保存修改':'保存后可直接带入私人房间'}</p><div class="button-row">${btn('导入 / 导出','advanced','secondary small')}${btn('保存构筑 ↗','save-build','small')}</div></div></div><aside class="workshop-aside"><div class="character-preview">${portrait(c,"portrait")}<div class="preview-text"><span class="eyebrow" id="preview-series">${esc(c.series)}</span><h3 id="preview-name">${esc(c.name)}</h3><p id="preview-title">${esc(c.title)}</p><span class="color-label ${c.color}" id="preview-color">${colors[c.color]} · ${c.hp} 体力</span></div></div><div id="budget-box" class="budget-box">正在校验构筑…</div><p class="help">积木描述不是可执行脚本。服务器会验证次数、费用与预算，普通牌池和模式胜利条件始终固定。<br><br>预算只控制内测准入，实际强度仍需通过对局数据调整。</p></aside></div>`;renderBudget();}

  function portrait(character,cls,extra=''){const c=character||{},art=(S.catalog.arts||[]).find(a=>a.id===c.art);return '<div class="'+cls+(art?' character-art':' art-'+(Number.isInteger(c.art)&&c.art>=0&&c.art<=3?c.art:0))+'">'+(art?'<img src="'+esc(art.url)+'" alt="'+esc(c.name||art.name)+'" loading="lazy" decoding="async">':'')+extra+'</div>';}
  function seriesOptions(){return Object.fromEntries([...new Set((S.catalog.presets||[]).map(b=>b.character.series))].map(s=>[s,s]));}
  function filteredCharacters(){const q=S.libraryQuery.trim().toLocaleLowerCase();return (S.catalog.presets||[]).filter(b=>(!S.librarySeries||b.character.series===S.librarySeries)&&(!q||[b.name,b.character.name,b.character.title,b.character.series,...b.character.skills.map(s=>s.name),S.catalog.characterNotes?.[b.character.id]?.summary||''].join(' ').toLocaleLowerCase().includes(q)));}
  function renderLibrary(){const packs=S.catalog.contentPacks||[];$('#main').innerHTML='<div class="page-heading"><div><span class="eyebrow">CHARACTERS & CREATOR PUZZLES</span><h1>遇见角色，也带走灵感。</h1><p>角色、技能与 IP 心象分别收藏，按自己的故事重新组合。</p></div>'+btn('我的拼图 / 分享','local-templates','secondary small')+'</div>'+packs.map(p=>'<div class="notice"><b>'+esc(p.name)+'</b> · '+p.characterIds.length+' 位角色<br>'+esc(p.description)+'</div>').join('')+'<div class="library-tools"><label>搜索角色<input id="library-search" type="search" value="'+esc(S.libraryQuery)+'" placeholder="名字、称号或技能…"></label><label>所属系列<select id="library-series">'+opt({'':'全部系列',...seriesOptions()},S.librarySeries)+'</select></label><div class="button-row">'+btn('经典技能拼图','browse-skills','secondary small','data-index="-1"')+btn('IP 心象牌库','browse-minds','secondary small','data-index="-1"')+'</div></div><div id="library-results"></div>';renderLibraryResults();}
  function renderLibraryResults(){const root=$('#library-results');if(!root)return;const matches=filteredCharacters(),pages=Math.max(1,Math.ceil(matches.length/12));S.libraryPage=Math.min(S.libraryPage,pages-1);const list=matches.slice(S.libraryPage*12,S.libraryPage*12+12);root.innerHTML='<div class="library-count">找到 '+matches.length+' 位角色 · 第 '+(S.libraryPage+1)+' / '+pages+' 页</div><div class="character-library-grid">'+list.map(b=>'<article class="library-character">'+portrait(b.character,'library-portrait')+'<div class="library-copy"><span class="eyebrow">'+esc(b.character.series)+'</span><h3>'+esc(b.character.name)+'</h3><p>'+esc(b.character.title)+'</p><div class="library-skill-names">'+b.character.skills.map(s=>'<span>'+esc(s.name)+'</span>').join('')+'</div>'+btn('查看角色与创作缘由','character-detail','secondary small','data-id="'+esc(b.id)+'"')+'</div></article>').join('')+'</div>'+(!list.length?'<p class="empty-state">没有找到角色，试试其他关键词。</p>':'')+'<div class="pagination">'+btn('上一页','library-prev','secondary small',S.libraryPage===0?'disabled':'')+'<span>'+(S.libraryPage+1)+' / '+pages+'</span>'+btn('下一页','library-next','secondary small',S.libraryPage>=pages-1?'disabled':'')+'</div>';}
  function characterDetail(id){const b=allBuilds().find(b=>b.id===id);if(!b)return;const c=b.character,n=S.catalog.characterNotes?.[c.id];showModal(c.name+' · '+c.title,'<div class="character-detail">'+portrait(c,'detail-portrait')+'<div><span class="color-label '+c.color+'">'+colors[c.color]+' · '+c.hp+' 体力</span><p>'+esc(n?.summary||c.series)+'</p>'+(n?'<p class="help">'+esc(n.reason)+'</p>':'')+'</div></div>'+c.skills.map(s=>'<article class="reference-card"><h3>'+esc(s.name)+'</h3><p>'+esc(skillSentence(s))+'</p></article>').join('')+'<h3 class="detail-heading">配套 IP 心象</h3>'+b.deck.filter(d=>d.type==='custom').map(d=>'<article class="reference-card"><h3>'+esc(d.custom.name)+'<small>'+ (d.custom.characterId?'额外角色专属':'同 IP 共享')+'</small></h3><p>'+esc(describeEffects(d.custom.effects))+'</p></article>').join('')+(n?'<p class="help">经典技能灵感：'+esc([...(n.skillReferences||[]),...(n.cardReferences||[])].join(' / '))+'</p>'+((n.sourceUrl||'').startsWith('https://')||(n.sourceUrl||'').startsWith('http://')?'<a class="source-link" href="'+esc(n.sourceUrl)+'" target="_blank" rel="noopener noreferrer">角色资料来源 ↗</a>':''):''),btn('选为出战构筑','choose-library-build','secondary small','data-id="'+esc(id)+'"')+btn('仅载入角色，保留牌组','load-library-character','secondary small','data-id="'+esc(id)+'"')+btn('编辑整套','edit-library-build','small','data-id="'+esc(id)+'"'));}
  function loadCharacter(build){if(!build)return;if(!S.editor)editorStart(selectedBuild());S.editor.character=clone(build.character);S.editor.rulesVersion=S.catalog.rulesVersion;S.editorEpoch++;markEditorChanged();navigate('workshop');toast('已载入角色；当前十三张心象及顺序已保留。');}
  function markEditorChanged(){S.editorDirty=true;S.validationError='';S.budget=null;if(S.view==='workshop')renderWorkshop();schedulePreview();}
  function loadLocalTemplates(){try{const raw=JSON.parse(readLocal('imaginary.puzzles.v1')||'{}');S.localTemplates={skills:Array.isArray(raw.skills)?raw.skills.filter(t=>t&&typeof t.id==='string'&&t.skill&&Array.isArray(t.skill.effects)).slice(0,100).map(t=>({...t,local:true,tags:Array.isArray(t.tags)?t.tags:[]})):[],minds:Array.isArray(raw.minds)?raw.minds.filter(t=>t&&typeof t.id==='string'&&t.card&&Array.isArray(t.card.effects)).slice(0,100).map(t=>({...t,local:true,tags:Array.isArray(t.tags)?t.tags:[]})):[]};}catch(_){S.localTemplates={skills:[],minds:[]};}}
  function persistTemplates(next){try{localStorage.setItem('imaginary.puzzles.v1',JSON.stringify(next));S.localTemplates=next;}catch(_){throw new Error('浏览器无法保存拼图库，请先导出备份或释放本地存储空间。');}}
  function templates(kind){return kind==='skill'?[...(S.catalog.skillTemplates||[]),...S.localTemplates.skills]:[...(S.catalog.mindTemplates||[]),...S.localTemplates.minds];}
  function openPuzzles(kind,index=-1,scope='all'){S.puzzle={kind,index,query:'',scope,series:kind==='mind'&&index>=0?(S.editor?.character.series||''):''};const isSkill=kind==='skill';showModal(isSkill?'经典技能 · 创作拼图':'IP 专属心象牌库','<p>'+ (isSkill?'选一个机制，改写它的名字、触发、条件、代价与效果。':'同 IP 默认共享；额外角色绑定可在卡槽中设置或留空。')+'</p><div class="puzzle-toolbar"><input id="puzzle-search" type="search" placeholder="搜索名称、灵感或标签…" aria-label="搜索拼图"><select id="puzzle-scope" aria-label="拼图来源">'+opt({all:'全部拼图',official:'内置拼图',local:'本地收藏'},scope)+'</select>'+(!isSkill?'<select id="puzzle-series" aria-label="限定系列">'+opt({'':'全部系列',...Object.fromEntries([...new Set(templates('mind').map(t=>t.series||t.card.series))].map(s=>[s,s])),...(S.editor?{[S.editor.character.series]:S.editor.character.series}:{})},S.puzzle.series)+'</select>':'')+'</div><div id="puzzle-results" class="puzzle-results"></div>',btn('导入 / 导出拼图','share-templates','secondary small'));renderPuzzleResults();}
  function renderPuzzleResults(){if(!S.puzzle||!$('#puzzle-results'))return;const p=S.puzzle,q=p.query.trim().toLocaleLowerCase(),isSkill=p.kind==='skill';const list=templates(p.kind).filter(t=>(p.scope!=='local'||t.local)&&(p.scope!=='official'||!t.local)&&(!p.series||(t.series||t.card?.series)===p.series)&&(!q||[t.name,t.reference,t.description,...(t.tags||[])].join(' ').toLocaleLowerCase().includes(q)));$('#puzzle-results').innerHTML='<p class="help">'+list.length+' 个拼图'+(p.index>=0?' · 应用至当前'+(isSkill?'技能 '+(p.index+1):'心象槽 '+(p.index+1)):'')+'</p>'+list.map(t=>'<article class="puzzle-card"><div class="puzzle-title"><h3>'+esc(t.name)+'</h3><span class="pill">'+esc(t.local?'本地收藏':t.game||t.series||'内置')+'</span></div><p>'+esc(t.description||'')+'</p><p class="skill-sentence">'+esc(isSkill?skillSentence(t.skill):describeEffects(t.card.effects))+'</p><div class="puzzle-tags">'+(t.tags||[]).map(tag=>'<span>'+esc(tag)+'</span>').join('')+'</div><small class="muted">'+esc(t.reference||'自创机制')+'</small><div class="template-actions">'+btn(isSkill?(p.index>=0?'替换当前技能':'添加到角色'):(p.index>=0?'放入当前心象槽':'选择心象槽'),'apply-puzzle','small','data-id="'+esc(t.id)+'"')+btn('下载拼图','download-puzzle','ghost small','data-id="'+esc(t.id)+'"')+(t.local?btn('删除收藏','remove-puzzle','ghost small','data-id="'+esc(t.id)+'"'):btn('收藏拼图','collect-puzzle','ghost small','data-id="'+esc(t.id)+'"'))+'</div></article>').join('')+(!list.length?'<div class="empty-state">没有找到相关拼图。</div>':'');}
  function puzzleExport(skills=S.localTemplates.skills,minds=S.localTemplates.minds){return {format:'imaginary-puzzles-v1',rulesVersion:S.catalog.rulesVersion,skillTemplates:skills.map(({local,...t})=>t),mindTemplates:minds.map(({local,...t})=>t)};}
  function showTemplateShare(){showModal('我的拼图库 · 本地收藏与分享','<p>已收藏 '+S.localTemplates.skills.length+' 个技能、'+S.localTemplates.minds.length+' 张心象。收藏保存在此浏览器；导出 JSON 可备份或交给其他创作者。</p><div class="template-actions">'+btn('浏览收藏技能','my-skills','secondary small')+btn('浏览收藏心象','my-minds','secondary small')+'</div><label>拼图 JSON<textarea id="puzzle-json" class="advanced-textarea" spellcheck="false">'+esc(JSON.stringify(puzzleExport(),null,2))+'</textarea></label><label>选择 JSON 文件<input id="puzzle-file" type="file" accept=".json,application/json"></label><p class="help">导入会逐项经过服务器结构与预算校验，通过后追加到本地收藏。规则版本：'+esc(S.catalog.rulesVersion)+'</p>',btn('下载全部收藏','download-templates','secondary')+btn('校验并导入拼图','import-templates',''));}
  function validationShell(){const b=clone(S.catalog.presets[0]);delete b.id;b.rulesVersion=S.catalog.rulesVersion;b.character.hp=4;b.character.flipColor=null;b.character.skills=[];b.deck=b.deck.map(d=>({rank:d.rank,type:S.catalog.mindOptions?.[d.rank]?.[0]||d.type}));return b;}
  async function validateTemplate(template,kind){if(!template||typeof template!=='object')throw new Error('拼图必须是一个对象。');const b=validationShell();if(kind==='skill')b.character.skills=[clone(template.skill)];else b.deck[0]={rank:b.deck[0].rank,type:'custom',custom:clone(template.card)};const data=await api('validate_build',{build:b});const payload=kind==='skill'?{skill:data.build.character.skills[0]}:{card:data.build.deck[0].custom,series:data.build.deck[0].custom.series};return {id:'local_'+uid(),name:String(template.name||payload.skill?.name||payload.card?.name||'未命名拼图').slice(0,80),reference:String(template.reference||'自创拼图').slice(0,160),description:String(template.description||'可继续编辑的创作拼图').slice(0,600),tags:Array.isArray(template.tags)?template.tags.filter(t=>typeof t==='string').slice(0,8).map(t=>t.slice(0,30)):[],local:true,...payload};}
  async function collectTemplate(template,kind){await ensureSession();const validated=await validateTemplate(template,kind),key=kind==='skill'?'skills':'minds';if(S.localTemplates[key].length>=100)throw new Error('每类最多收藏 100 个拼图，请导出后清理。');persistTemplates({...S.localTemplates,[key]:[...S.localTemplates[key],validated]});toast('已加入本地拼图库，可编辑、复用与导出。');if($('#puzzle-results'))renderPuzzleResults();}
  function ensureEditor(){if(!S.editor)editorStart(selectedBuild());}
  function applyPuzzle(template,kind,index){ensureEditor();if(kind==='skill'){const skills=S.editor.character.skills;if(index<0&&skills.length>=2){showModal('选择要替换的技能','<p>每位角色最多 2 个技能。请选择一个位置替换为「'+esc(template.name)+'」。</p>'+skills.map((s,i)=>btn('替换 '+esc(s.name),'apply-puzzle-at','secondary','data-id="'+esc(template.id)+'" data-index="'+i+'"')).join(''));return;}if(index>=0)skills[index]=clone(template.skill);else skills.push(clone(template.skill));}else{if(index<0){showModal('选择心象槽位','<p>将「'+esc(template.name)+'」放入牌组，保留原有点数与抽取顺序。</p><div class="slot-picker">'+S.editor.deck.map((d,i)=>btn(rank(d.rank)+' · '+esc(d.type==='custom'?d.custom.name:S.catalog.cards[d.type].name),'apply-puzzle-at','secondary small','data-id="'+esc(template.id)+'" data-index="'+i+'"')).join('')+'</div>');return;}if(S.editor.deck[index].type!=='custom'&&S.editor.deck.filter(d=>d.type==='custom').length>=4){toast('限定心象最多 4 张，请替换已有的限定槽位。',true);return;}S.editor.deck[index]={rank:S.editor.deck[index].rank,type:'custom',custom:clone(template.card)};}$('#modal').close();S.view='workshop';markEditorChanged();navigate('workshop');toast(kind==='skill'?'技能拼图已载入，各项机制都可继续编辑。':'心象拼图已载入；可修改系列与可选角色绑定。');}
  function openArt(){showModal('角色立绘库','<input id="art-search" type="search" placeholder="搜索角色立绘…" aria-label="搜索角色立绘"><div id="art-results" class="art-library"></div>');renderArtResults('');}
  function renderArtResults(query){const list=(S.catalog.arts||[]).filter(a=>a.name.includes(query));$('#art-results').innerHTML=[0,1,2,3].map(n=>'<button class="art-choice" data-action="choose-art" data-index="'+n+'">'+portrait({art:n},'art-thumbnail')+'<span>通用立绘 '+(n+1)+'</span></button>').join('')+list.map(a=>'<button class="art-choice" data-action="choose-art" data-id="'+esc(a.id)+'">'+portrait({art:a.id,name:a.name},'art-thumbnail')+'<span>'+esc(a.name)+'</span></button>').join('');}
  function handleLibraryAction(action,el,index,id){if(action==='library-prev'||action==='library-next'){S.libraryPage+=action==='library-next'?1:-1;renderLibraryResults();return true;}if(action==='character-detail'){characterDetail(id);return true;}if(action==='choose-library-build'){S.selectedBuild=id;writeLocal('imaginary.build',id);$('#modal').close();toast('已选为出战构筑，可回大厅开始练习。');return true;}if(action==='load-library-character'||action==='edit-library-build'){const b=allBuilds().find(b=>b.id===id);$('#modal').close();action==='load-library-character'?loadCharacter(b):editorStart(b);return true;}if(action==='confirm-load-character'){const b=allBuilds().find(b=>b.id===$('#build-picker').value);$('#modal').close();loadCharacter(b);return true;}if(action==='browse-art'){openArt();return true;}if(action==='choose-art'){S.editor.character.art=id||index;$('#modal').close();markEditorChanged();return true;}if(action==='browse-skills'||action==='browse-minds'){openPuzzles(action==='browse-skills'?'skill':'mind',Number.isNaN(index)?-1:index);return true;}if(action==='local-templates'||action==='share-templates'){showTemplateShare();return true;}if(action==='my-skills'||action==='my-minds'){openPuzzles(action==='my-skills'?'skill':'mind',-1,'local');return true;}if(action==='download-templates'){download('心象实验室-创作拼图库.json',puzzleExport());return true;}if(['apply-puzzle','apply-puzzle-at','download-puzzle','collect-puzzle','remove-puzzle'].includes(action)){const kind=S.puzzle.kind,t=templates(kind).find(t=>t.id===id);if(!t)return true;if(action==='apply-puzzle'||action==='apply-puzzle-at')applyPuzzle(t,kind,action==='apply-puzzle-at'?index:S.puzzle.index);if(action==='download-puzzle')download(t.name+'.json',puzzleExport(kind==='skill'?[t]:[],kind==='mind'?[t]:[]));if(action==='collect-puzzle')run(()=>collectTemplate(t,kind));if(action==='remove-puzzle')run(async()=>{const key=kind==='skill'?'skills':'minds';persistTemplates({...S.localTemplates,[key]:S.localTemplates[key].filter(t=>t.id!==id)});renderPuzzleResults();toast('已移除本地收藏，正在编辑的内容不受影响。');});return true;}if(action==='save-skill-template'||action==='save-mind-template'){const kind=action==='save-skill-template'?'skill':'mind',payload=kind==='skill'?S.editor.character.skills[index]:S.editor.deck[index].custom;run(()=>collectTemplate({name:payload.name,[kind==='skill'?'skill':'card']:clone(payload)},kind));return true;}if(action==='import-templates'){run(async()=>{const raw=JSON.parse($('#puzzle-json').value);if(raw?.format!=='imaginary-puzzles-v1'||!Array.isArray(raw.skillTemplates)||!Array.isArray(raw.mindTemplates))throw new Error('请选择创作拼图库格式的 JSON 文件。');if(raw.rulesVersion&&!['0.1.0-alpha',S.catalog.rulesVersion].includes(raw.rulesVersion))throw new Error('不支持此拼图库的规则版本。');if(!raw.skillTemplates.length&&!raw.mindTemplates.length)throw new Error('文件中没有拼图。');if(raw.skillTemplates.length+S.localTemplates.skills.length>100||raw.mindTemplates.length+S.localTemplates.minds.length>100)throw new Error('每类拼图的本地收藏上限为 100 个。');await ensureSession();const skills=[],minds=[];for(const t of raw.skillTemplates)skills.push(await validateTemplate(t,'skill'));for(const t of raw.mindTemplates)minds.push(await validateTemplate(t,'mind'));persistTemplates({skills:[...S.localTemplates.skills,...skills],minds:[...S.localTemplates.minds,...minds]});showTemplateShare();toast('全部 '+(skills.length+minds.length)+' 个拼图校验通过并已收藏。');});return true;}return false;}

  function getPath(path){return path.split('.').reduce((o,k)=>o[k],S.editor);}
  function setPath(path,value){const parts=path.split('.');const key=parts.pop();const obj=parts.reduce((o,k)=>o[k],S.editor);obj[key]=value;}
  function editorChange(el){let value=el.value;const path=el.dataset.field;if(/\.(hp|hand|mind|amount|limit)$/.test(path))value=Number(value);if(path==='character.flipColor'&&value==='')value=null;setPath(path,value);if(/\.custom\.characterId$/.test(path)&&value==='')delete getPath(path.split('.').slice(0,-1).join('.')).characterId;let redraw=false;if(/^deck\.\d+\.type$/.test(path)){const d=S.editor.deck[Number(path.split('.')[1])];if(value==='custom')d.custom={name:'未命名心象',series:S.editor.character.series,fallback:'recover',effects:[{op:'draw',amount:1,target:'self',color:'neutral'}]};else delete d.custom;redraw=true;}else if(/\.effects\.\d+\.op$/.test(path)){const effect=getPath(path.split('.').slice(0,-1).join('.'));const meta=S.catalog.blocks.effectMeta?.[value];if(meta){if(!meta.targets.includes(effect.target))effect.target=meta.targets[0];effect.amount=Math.min(meta.max,Math.max(meta.min,effect.amount));}redraw=true;}else if(/character\.skills\.\d+\.trigger$/.test(path)){const skill=getPath(path.split('.').slice(0,-1).join('.'));if(value==='convert'){skill.conversion={from:'attack',to:'defense'};skill.effects=[];}else{delete skill.conversion;if(!skill.effects?.length)skill.effects=[{op:'draw',amount:1,target:'self',color:'neutral'}];}redraw=true;}else if(path==='character.color'){if(value==='neutral'||S.editor.character.flipColor===value)S.editor.character.flipColor=null;redraw=true;}S.editorDirty=true;if(redraw)renderWorkshop();$('#save-state')&&($('#save-state').textContent='有未保存修改');updateEditorPreview();schedulePreview();}
  function updateEditorPreview(){const c=S.editor?.character;if(!c)return;$('#preview-name')&&($('#preview-name').textContent=c.name);$('#preview-title')&&($('#preview-title').textContent=c.title);$('#preview-series')&&($('#preview-series').textContent=c.series);if($('#preview-color')){$('#preview-color').textContent=`${colors[c.color]} · ${c.hp} 体力`;$('#preview-color').className='color-label '+c.color;}$$('[data-skill-preview]').forEach(el=>el.textContent=skillSentence(c.skills[Number(el.dataset.skillPreview)]));}
  function schedulePreview(){clearTimeout(S.previewTimer);S.previewTimer=setTimeout(previewBuild,650);}
  function estimateBudget(b){const meta=S.catalog.blocks.effectMeta||{};const cost=e=>(meta[e.op]?.cost||0)*e.amount+(['damage','attack'].includes(e.op)&&e.color==='neutral'?e.amount:0);let character=(b.character.hp-4)*2+(b.character.flipColor?2:0);for(const s of b.character.skills){let value=s.trigger==='convert'?(s.conversion?.from==='hand'?4:3):(s.effects||[]).reduce((sum,e)=>sum+cost(e),0);if(!['active','convert'].includes(s.trigger))value+=2;character+=Math.max(1,value-Math.min(4,(s.cost?.hand||0)+(s.cost?.mind||0)*2))*(s.limit||1);}const cards=b.deck.filter(d=>d.type==='custom').map(d=>d.custom.effects.reduce((sum,e)=>sum+cost(e),0)),custom=cards.reduce((sum,n)=>sum+n,0);return {character,characterMax:18,custom,customMax:24,used:character+custom,max:42,cards,local:true};}
  async function previewBuild(){if(!S.editor)return;if(!S.token){S.budget=estimateBudget(S.editor);S.validationError=S.budget.character>18?'人物预算超限，请降低数值或增加费用。':S.budget.custom>24?'限定牌总预算超过 24。':S.budget.cards.some(n=>n>12)?'单张限定牌预算超过 12。':'';renderBudget();return;}const sequence=++S.previewSequence,epoch=S.editorEpoch,snapshot=JSON.stringify(S.editor);try{const data=await api('validate_build',{build:JSON.parse(snapshot)},{keepAuth:true});if(sequence!==S.previewSequence||epoch!==S.editorEpoch||JSON.stringify(S.editor)!==snapshot)return;S.budget=data.budget;S.validationError='';}catch(error){if(sequence!==S.previewSequence||epoch!==S.editorEpoch||JSON.stringify(S.editor)!==snapshot)return;S.validationError=error.message;S.budget=null;}renderBudget();}
  function renderBudget(){const el=$('#budget-box');if(!el)return;if(S.validationError){el.className='budget-box invalid';el.innerHTML=`<b>需要调整</b><p style="margin:8px 0 0;color:inherit">${esc(S.validationError)}</p>`;return;}el.className='budget-box';if(!S.budget){el.textContent='正在校验构筑…';return;}const b=S.budget;el.innerHTML=`<span class="eyebrow" style="color:var(--green);margin-bottom:5px">BUILD CHECK</span><div><strong>${b.character??b.used}</strong> <span class="muted">/ ${b.characterMax??b.max} 人物预算</span></div><div class="budget-meter"><i style="width:${Math.min(100,100*(b.character??b.used)/(b.characterMax??b.max))}%"></i></div><div>限定牌预算　<b>${b.custom??0}</b> / ${b.customMax??24}</div><p style="font-size:10px;margin:10px 0 0;color:var(--green)">${b.local?'本地预算估算 · 保存时服务器校验':'✓ 构筑结构通过校验'}</p>`;}
  async function saveBuild(){const editor=S.editor,epoch=S.editorEpoch,snapshot=JSON.stringify(editor);clearTimeout(S.previewTimer);S.previewSequence++;await ensureSession();const data=await api('save_build',{build:JSON.parse(snapshot)});S.selectedBuild=data.build.id;writeLocal('imaginary.build',S.selectedBuild);const unchanged=epoch===S.editorEpoch&&JSON.stringify(S.editor)===snapshot;if(epoch===S.editorEpoch){if(unchanged){S.editor=data.build;S.budget=data.budget;S.editorDirty=false;S.validationError='';}else if(!S.editor.id){S.editor.id=data.build.id;}}await refreshMe();if(S.view==='workshop'&&epoch===S.editorEpoch)renderWorkshop();toast(unchanged?'构筑已保存，可在大厅选择它加入内测。':'已保存提交时的版本；后续修改仍留在工坊，请再次保存。');if(!unchanged&&epoch===S.editorEpoch)schedulePreview();}
  function loadExamples(){showModal('角色与牌组可以分开创作',`<p>载入整套会替换角色及十三张心象；只载入角色会保留当前心象牌组。</p>${buildPicker()}`,btn('仅载入角色，保留 13 张心象','confirm-load-character','secondary')+btn('载入整套构筑','confirm-load',''));}
  function renderReference(){const rules=[['01 / 一回合怎样展开','<ol><li><strong>回合开始：</strong>延时牌判定、装备成熟、触发技能。</li><li><strong>抽牌：</strong>通常摸 2 张普通牌，可以用 0～2 张心象替代。</li><li><strong>出牌：</strong>打出事件、装上永续牌、使用技能；通常限一次攻击。</li><li><strong>弃牌：</strong>手牌超出当前有效体力时，选择弃牌至上限。</li></ol>'],['02 / 精神、肉体与颜色','<p>冷暖对抗中，异色伤害留下对应颜色指示物，当前异色指示物抵消精神。无色伤害直接降低肉体上限。精神或肉体降至 0 时出局；有异色翻面的角色，精神耗尽可翻面一次，指示物保留。系列对抗中所有伤害统一扣除有效体力。</p><p>冷暖阵营获胜：存活者仅剩同色。无色角色必须独自存活。系列模式：只剩同一系列。</p>'],['03 / 心象与心坏','<p>开局 5 张普通手牌；每人另有自己预先排列的 <strong>13 张心象</strong>。A～K 各一张，A = 1、J = 11、Q = 12、K = 13。抽取、弃掉与查看默认仅作用于牌顶。</p><p>心象使用或弃置后进入其拥有者的已耗区，不进入普通弃牌堆。心象牌组为空即进入<strong>心坏</strong>：技能失效、攻击范围归零、无法回复体力。补回心象即可解除心坏。</p>'],['04 / 永续与响应','<p>延时基本牌装到角色上，下个自己的回合才成熟。发动时卸除；「宝藏」持续加伤，但卸除要承受代价。「防御」具有防守属性，「回避」具有躲避属性。面对攻击或事件，界面会列出当前可用响应。</p><p>距离按存活角色座次计算，默认攻击范围为 1。机器人和超时处理使用同一套规则。</p>'],['05 / 本次内测的裁定','<p>仅开放冷暖对抗与系列对抗。奇迹采用座次顺序自动救援；有费用的自动技能按手牌左侧、心象牌顶支付。每个技能按设定每个全局回合最多 1～2 次。房主可限制自创构筑，所有构筑均经过服务器预算校验。</p><p>未尽歧义与实现边界已写入项目规则文档；本版本的裁定用于内测，不视为原设计原文。</p>']];$('#main').innerHTML=`<div class="page-heading"><div><span class="eyebrow">RULEBOOK & CARD ARCHIVE</span><h1>规则清晰，想象才有余地。</h1><p>普通牌池共 104 张，所有玩家共享；角色与心象构筑由你创造。</p></div>${btn('返回大厅','go-home','secondary small')}</div><div class="reference-grid"><section class="panel">${rules.map(([title,body])=>`<div class="rule-section"><h3>${title}</h3>${body}</div>`).join('')}<div class="documentation-links" style="margin-top:18px"><a href="rules.html" target="_blank" rel="noopener noreferrer">完整内测规则与裁定 ↗</a><a href="https://number81.xyz/index.php?topic=3575.0" target="_blank" rel="noopener noreferrer">阅读设计原帖 ↗</a><button class="text-button" data-action="feedback">反馈规则问题 ↗</button></div></section><section class="panel"><div class="panel-title"><h2>普通牌索引</h2><span class="small-text muted">${Object.keys(S.catalog.cards).length} 种效果</span></div><input class="reference-search" id="card-search" aria-label="检索牌名或效果" placeholder="搜索牌名、效果或属性…" value="${esc(S.cardFilter)}"><div id="reference-results">${referenceCards()}</div></section></div>`;}
  function referenceCards(){return Object.values(S.catalog.cards).filter(c=>(c.name+c.description+kinds[c.kind]).includes(S.cardFilter)).map(c=>`<article class="reference-card"><h3>${esc(c.name)}<small>${kinds[c.kind]||c.kind}</small></h3><p>${esc(c.description)}</p></article>`).join('')||'<div class="empty-state">没有找到相关卡牌</div>';}
  function renderRoom(){const room=S.room;if(!room){renderHome();return;}if(room.game){renderGame();return;}const isHost=room.hostId===S.user?.id;$('#main').innerHTML=`<div class="page-heading"><div><span class="eyebrow">PRIVATE PLAYTEST ROOM</span><h1>${esc(room.name)}</h1><p>分享房间码，邀请朋友带着他们的心象入座。</p></div>${btn('退出房间','leave-room','secondary small')}</div><div class="lobby-layout"><section><div class="section-heading"><h2>等待入座 <small>${room.players.length} / 6 PLAYERS</small></h2><span class="pill">${S.catalog.modes[room.mode]}</span></div><div class="seat-list">${room.players.map(p=>`<article class="seat">${portrait(p.character,"seat-portrait")}<div><h3>${esc(p.name)} ${p.id===room.hostId?'<span class="small-text muted">房主</span>':''}</h3><p>${esc(p.character?.name||'等待选择')} · ${colors[p.character?.color]||''}${p.bot?' · 机器人':''}</p><span class="color-label ${p.character?.color||'cool'}">${esc(p.character?.series||'')}</span></div></article>`).join('')}${Array.from({length:Math.max(0,Math.min(6-room.players.length,4))},()=>'<div class="seat empty">＋ 等待另一个心象</div>').join('')}</div><div class="notice" style="margin-top:22px">${room.allowCustom?'允许自创构筑；所有角色与限定牌都需通过预算校验。':'此房间只允许使用系统范例构筑。'}<br>至少 2 人，并且需要有互相对抗的阵营，才能开始游戏。</div></section><aside class="room-controls"><section class="panel"><span class="eyebrow">INVITATION CODE</span><div class="room-code">${esc(room.code)}</div>${btn('复制邀请码','copy-code','secondary small')}<p class="help">身份与房间记录保存在本浏览器。刷新页面会自动重连。</p></section><section class="panel"><h3>出战准备</h3><label>当前构筑${buildPicker()}</label>${btn('切换出战构筑','choose-build','secondary small')}${isHost?`${btn('＋ 添加机器人','add-bot','secondary',room.players.length>=6?'disabled':'')}${btn('全员就绪 · 开始对局 →','start-game','',room.players.length<2?'disabled':'')}`:'<p class="help">等待房主开始对局…</p>'}</section></aside></div>`;}
  function health(p){const hp=Math.max(0,p.hp||0),max=Math.max(0,p.maxHp||0);return `<div class="health" aria-label="体力 ${hp} / ${max}">${Array.from({length:Math.min(max,12)},(_,i)=>`<i class="health-pip ${i>=hp?'empty':''}"></i>`).join('')}<span class="health-text">${hp} / ${max}</span></div>`;}
  function playerBoard(p,g){return `<article class="player-board ${g.turn===p.id?'active-turn':''} ${S.selectedTarget===p.id?'targeted':''} ${!p.alive?'dead':''}">${portrait(p.character,"player-art",`<span class="player-name">${esc(p.character?.name||p.name)}</span>`)}${p.alive?`<button class="player-target" data-action="target" data-id="${esc(p.id)}" aria-pressed="${S.selectedTarget===p.id}">${S.selectedTarget===p.id?'✓ 已选择':'选为目标'}</button>`:''}<div class="player-meta"><div class="meta-top"><span>${esc(p.name)}</span><span class="color-label ${p.color}">${colors[p.color]}</span></div>${health(p)}<div class="player-counts"><span>手牌 ${p.handCount}</span><span>心象 ${p.mindCount}</span>${p.shield?`<span>盾 ${p.shield}</span>`:''}</div>${p.broken?'<span class="slot-custom-badge">心坏 · 技能失效</span>':''}${!p.alive?'<span class="slot-custom-badge">已出局</span>':''}<div class="equipment-list">${(p.equipment||[]).map(c=>`<span class="equipment-chip" title="${esc(c.description||cardDef(c).description)}">${esc(cardName(c))}${c.ready===false?' ◷':''}</span>`).join('')}${(p.delayed||[]).map(c=>`<span class="equipment-chip delayed">${esc(cardName(c))}</span>`).join('')}</div>${p.spent?.length?`<details style="margin-top:8px"><summary style="font-size:9px;color:var(--muted)">已耗心象 ${p.spent.length}</summary><div class="mind-strip">${p.spent.map(c=>`<div class="mind-token spent" title="${esc(cardName(c))}">${rank(c.rank)}<small>${esc(cardName(c))}</small></div>`).join('')}</div></details>`:''}</div></article>`;}
  function physicalCard(c,selectable=true){const type=c.type;return `<button class="playing-card ${c.origin==='mind'?'mind-card':''} ${type==='attack_warm'?'attack-warm':''} ${S.selectedCard===c.uid?'selected':''}" data-action="${selectable?'select-card':'noop'}" data-id="${esc(c.uid)}" aria-label="${esc(rank(c.rank)+' '+cardName(c))}" aria-pressed="${S.selectedCard===c.uid}" title="${esc(c.description||cardDef(c).description)}"><span class="card-top">${rank(c.rank)}<span class="suit">${esc(c.suit||'◇')}</span></span><span class="card-symbol" aria-hidden="true">${type?.includes('attack')?'✦':type==='defense'?'◈':cardDef(c).kind==='persistent'?'∞':c.type==='custom'?'✧':'◌'}</span><span class="card-name">${esc(cardName(c))}</span><span class="card-origin">${c.origin==='mind'?'心象 · MIND':'普通 · COMMON'}</span></button>`;}
  function legal(){return S.room?.game?.legalActions||[];}
  function legalButton(item,index,cls='secondary small'){let label=item.label||'确认操作';const g=S.room?.game;if((item.action?.type==='respond'||item.action?.conversion!=null)&&item.action.card&&g){const c=[...(g.me?.hand||[]),...(g.players.find(p=>p.id===g.me?.id)?.equipment||[]),...(g.pending?.cards||[])].find(c=>c.uid===item.action.card);if(c)label+=` · ${rank(c.rank)} ${c.origin==='mind'?'心象':'普通'}`;}return `<button class="btn ${cls}" data-action="legal" data-index="${index}">${esc(label)}</button>`;}
  function updateDeadline(){const el=$('#deadline-count'),g=S.room?.game;if(!el||!g?.deadline)return;const seconds=Math.max(0,Math.ceil(g.deadline-(Date.now()+S.serverOffset)/1000));el.textContent=`操作剩余 ${seconds} 秒`;el.style.color=seconds<=15?'var(--coral)':'';}
  function costControls(chosen,type,candidates,g){const hand=g.me.hand||[];if(candidates.some(({item})=>item.action.costCard)){const valid=hand.filter(c=>c.uid!==chosen.uid);if(!valid.some(c=>c.uid===S.costCard))S.costCard=valid[0]?.uid||'';return `<label style="margin-bottom:13px">额外弃手牌的方式使用以下卡支付<select id="action-cost-card">${valid.map(c=>`<option value="${esc(c.uid)}" ${c.uid===S.costCard?'selected':''}>${rank(c.rank)} ${esc(cardName(c))}${c.origin==='mind'?'（心象）':''}</option>`).join('')}</select></label>`;}if(type==='skill'){const skill=g.me.skills[S.selectedSkill];const count=skill?.cost?.hand||0;if(count){S.costSelection=S.costSelection.filter(id=>hand.some(c=>c.uid===id));return `<p class="help" style="margin-bottom:6px">此技能需弃 ${count} 张手牌。可自行勾选；不选则按手牌左侧支付。</p><div class="selection-cards">${hand.map(c=>`<label class="selection-chip"><input type="checkbox" data-cost-card="${esc(c.uid)}" ${S.costSelection.includes(c.uid)?'checked':''}>${rank(c.rank)} ${esc(cardName(c))}</label>`).join('')}</div>`;}}return '';}
  function giftControls(type,g){if(type!=='skill')return '';const count=(g.me.skills[S.selectedSkill]?.effects||[]).filter(e=>e.op==='give_hand').reduce((n,e)=>n+e.amount,0);if(!count)return '';const hand=g.me.hand||[];S.giveSelection=S.giveSelection.filter(id=>hand.some(c=>c.uid===id));return '<p class="help">赠送 '+count+' 张手牌，可指定卡牌；不选则在支付费用后按左侧手牌赠送。赠送牌不能同时作为费用。</p><div class="selection-cards">'+hand.map(c=>'<label class="selection-chip"><input type="checkbox" data-give-card="'+esc(c.uid)+'" '+(S.giveSelection.includes(c.uid)?'checked':'')+'>'+rank(c.rank)+' '+esc(cardName(c))+'</label>').join('')+'</div>';}
  function renderGame(){const room=S.room,g=room.game;const me=g.players.find(p=>p.id===S.user?.id)||g.players.find(p=>p.id===g.me?.id);const current=g.players.find(p=>p.id===g.turn);const myturn=g.turn===me?.id;const hand=g.me?.hand||[];if(!hand.some(c=>c.uid===S.selectedCard))S.selectedCard=null;const finished=g.status==='finished'||room.status==='finished';$('#main').innerHTML=`<div class="match-top"><div><span class="eyebrow">${S.catalog.modes[g.mode]||'PRIVATE PLAYTEST'} · ${esc(room.code)}</span><h1>${esc(room.name)}</h1><p>第 ${g.turnNumber||1} 回合 · 牌堆 ${g.deckCount??'—'} · 弃牌 ${g.discardCount??'—'}</p></div><div class="button-row">${btn('复制房间码','copy-code','secondary small')}${btn('导出复盘','export-game','secondary small')}</div></div>${finished?`<section class="winner-banner"><span class="eyebrow">THIS CHAPTER IS COMPLETE</span><h2>此刻，胜负已分。</h2><p class="winner-name">${esc(typeof g.winner==='string'?g.winner:JSON.stringify(g.winner||'平局'))}</p><div class="button-row" style="justify-content:center">${btn('返回大厅','go-home','secondary small')}${btn('记录本局反馈','feedback','small')}</div></section>`:`<section class="turn-banner"><div><strong>${myturn?'轮到你了。':`${esc(current?.name||'角色')} 的回合`}</strong><p>${myturn?'每次选择，都在改写你的心象。':'观察局势，等待属于你的时刻。'}${me&&!me.alive?' 你已出局，可继续观战。':''}</p></div><span class="phase-tag">${phases[g.phase]||esc(g.phase)}<span id="deadline-count" style="display:block;font-size:9px;margin-top:2px">操作剩余 ${Math.max(0,Math.ceil(g.deadline-(Date.now()+S.serverOffset)/1000))} 秒</span></span></section>`}<div class="game-layout"><div><div class="opponents">${g.players.filter(p=>p.id!==me?.id).map(p=>playerBoard(p,g)).join('')}</div>${g.pending?renderPending(g):''}${me?`<section class="self-board"><div class="self-title">${portrait(me.character,"seat-portrait")}<div><h3>${esc(me.character?.name||me.name)} <span class="small-text muted">你</span></h3><p>${esc(me.name)} · ${esc(me.series)} · ${colors[me.color]}${me.broken?' · 心坏':''}</p></div>${health(me)}</div><div class="hand-label"><span>手牌 / ${hand.length} 张${g.phase==='discard'&&myturn?' · 选择需要弃掉的牌':''}</span><span>攻击范围 ${me.range??1} · 护盾 ${me.shield||0}</span></div><div class="hand-cards">${hand.length?hand.map(c=>physicalCard(c)).join(''):'<p class="small-text muted" style="padding:30px 15px">暂无手牌</p>'}</div>${g.phase==='discard'&&myturn?renderDiscard(hand,me):renderActionPanel(g,me)}<div class="skill-buttons">${(g.me?.skills||me.character?.skills||[]).map((s,i)=>`<button class="skill-button" data-action="select-skill" data-index="${i}" title="${esc(s.description||skillSentence(s))}" ${me.broken?'disabled':''}>◇ ${esc(s.name)}${s.used?' · 已用':''}</button>`).join('')}${(me.equipment||[]).map(c=>`<button class="skill-button" data-action="select-equipment" data-id="${esc(c.uid)}">∞ ${esc(cardName(c))}${c.ready===false?' · 未成熟':''}</button>`).join('')}</div>${(me.delayed||[]).length?`<div class="equipment-list" style="margin-top:12px"><span class="help" style="margin:0">我的延时区：</span>${me.delayed.map(c=>`<span class="equipment-chip delayed" title="${esc(c.description||cardDef(c).description)}">${esc(cardName(c))} · 抽牌前判定</span>`).join('')}</div>`:''}<div class="hand-label" style="margin-top:21px"><span>我的心象 / ${me.mindCount} 张 · 从左向右抽取</span><span>已耗 ${me.spentCount} 张</span></div><div class="mind-strip">${(g.me?.mind||[]).map((c,i)=>`<div class="mind-token" title="第 ${i+1} 张：${esc(cardName(c))}">${rank(c.rank)}<small>${esc(cardName(c))}</small></div>`).join('')||'<span class="small-text muted">心象牌组已空，补回心象可解除心坏。</span>'}</div>${(g.me?.spent||[]).length?`<details><summary class="small-text muted">查看已耗心象</summary><div class="mind-strip">${g.me.spent.map(c=>`<div class="mind-token spent" title="${esc(cardName(c))}">${rank(c.rank)}<small>${esc(cardName(c))}</small></div>`).join('')}</div></details>`:''}</section>`:''}<div class="turn-actions">${legal().map((item,i)=>({item,i})).filter(({item})=>['draw','end'].includes(item.action?.type)).map(({item,i})=>legalButton(item,i,item.action.type==='end'?'secondary':'')).join('')}</div>${!legal().length&&!finished?'<p class="help">正在等待其他角色或服务器推进对局。中途可刷新页面重连。</p>':''}</div><aside class="game-side"><section class="panel log-panel"><h3>对局手记 <span class="small-text muted">LIVE</span></h3>${(g.log||[]).slice(-35).map(l=>`<div class="log-entry">${esc(typeof l==='string'?l:l.text)}</div>`).join('')}<div class="log-stats">房间版本 ${room.revision}<br>规则 ${esc(S.catalog.rulesVersion)}<br><button class="text-button" data-action="feedback">提交这一局的反馈 ↗</button></div></section></aside></div>`;}
  function renderActionPanel(g,me){let chosen=null,type='play';if(S.selectedCard)chosen=(g.me.hand||[]).find(c=>c.uid===S.selectedCard);else if(S.selectedEquipment){chosen=(me.equipment||[]).find(c=>c.uid===S.selectedEquipment);type='equip_use';}else if(S.selectedSkill!==null){const skill=(g.me.skills||me.character.skills||[])[S.selectedSkill];if(skill){chosen={name:skill.name,description:skill.description||skillSentence(skill)};type=skill.trigger==='convert'?'convert':'skill';}}
    if(!chosen)return `<div class="action-panel"><p style="margin:0">${g.phase==='draw'&&g.turn===me.id?'在下方选择普通牌与心象的抽取比例。':'点击一张手牌、技能或装备查看效果与可用操作。'}${S.selectedTarget?` 当前目标：${esc(g.players.find(p=>p.id===S.selectedTarget)?.name||'')}`:''}</p>${S.selectedTarget?btn('清除目标','clear-target','ghost small'):''}</div>`;
    let candidates=legal().map((item,i)=>({item,i})).filter(({item})=>(type==='convert'?item.action.conversion===S.selectedSkill:type==='play'?item.action?.type==='play'&&item.action.card===chosen.uid:item.action?.type===type&&(type==='skill'?item.action.index===S.selectedSkill:item.action.card===chosen.uid)));const all=candidates;const hasTargets=all.some(({item})=>item.action.target);if(S.selectedTarget&&hasTargets)candidates=all.filter(({item})=>!item.action.target||item.action.target===S.selectedTarget);return `<div class="action-panel"><div class="panel-title" style="margin-bottom:6px"><h3>${esc(chosen.name||cardName(chosen))}</h3><button class="icon-button" data-action="clear-card" aria-label="取消选择">×</button></div><p>${esc(chosen.description||cardDef(chosen).description||'使用下方规则按钮结算。')}</p>${hasTargets?`<label style="margin-bottom:12px">目标<select id="action-target"><option value="">显示全部可用目标</option>${g.players.filter(p=>p.alive&&all.some(({item})=>item.action.target===p.id)).map(p=>`<option value="${esc(p.id)}" ${p.id===S.selectedTarget?'selected':''}>${esc(p.name)} · ${esc(p.character?.name||'')}</option>`).join('')}</select></label>`:''}${costControls(chosen,type,all,g)}${giftControls(type,g)}<div class="button-row">${candidates.map(({item,i})=>legalButton(item,i,'small')).join('')||'<span class="help">当前没有可用操作。可能尚未成熟、不在范围内、费用不足或时机不符。</span>'}</div>${S.selectedTarget&&hasTargets?btn('显示全部目标','clear-target','ghost small'):''}</div>`;}
  function renderPending(g){const pending=g.pending;const responder=g.players.find(p=>p.id===(pending.player||pending.playerId));const mine=(pending.player||pending.playerId)===g.me?.id||legal().some(l=>l.action?.type==='respond');let candidates=legal().map((item,i)=>({item,i})).filter(({item})=>item.action?.type==='respond');return `<section class="action-panel response-panel" style="margin-bottom:18px"><span class="eyebrow">${mine?'YOUR RESPONSE':'WAITING FOR RESPONSE'}</span><h3>${esc(pending.prompt||'等待响应')}</h3><p>${mine?'请在下面选择你的响应。':`等待 ${responder?.name||'其他角色'} 作出选择。`}</p>${pending.revealed?`<p>判定结果：${rank(pending.revealed.rank)} ${esc(cardName(pending.revealed))}</p>`:''}${mine?`<div class="response-options">${candidates.map(({item,i})=>legalButton(item,i,'small')).join('')}</div>${renderPendingSelection(pending)}`:''}</section>`;}
  function renderPendingSelection(p){if(!p.cards||!p.cards.length)return '';if(!['reset','rebuild','scry'].includes(p.kind))return `<div class="selection-cards">${p.cards.map(c=>`<span class="selection-chip">${rank(c.rank)} ${esc(cardName(c))}</span>`).join('')}</div>`;return `<div class="help">${p.kind==='scry'?'将全部展示的普通牌按点击次序放回普通牌顶。':'自选卡牌按点击次序排列。'}已选 <span id="selection-count">${S.selection.length}</span> 张${p.count!=null?`，需要 ${p.count} 张`:''}。</div><div class="selection-cards">${p.cards.map(c=>`<label class="selection-chip"><input type="checkbox" data-select-card="${esc(c.uid)}" ${S.selection.includes(c.uid)?'checked':''}>${rank(c.rank)} ${esc(cardName(c))}</label>`).join('')}</div><div id="selection-order" class="help">${selectionOrder(p.cards)}</div>${btn('确认自选顺序','pending-selection','secondary small')}`;}
  function selectionOrder(cards){return S.selection.length?(S.room?.game?.pending?.kind==='scry'?'普通牌顶 → 牌底：':'置底顺序：')+S.selection.map((id,i)=>{const c=cards.find(c=>c.uid===id);return c?`${i+1}. ${esc(rank(c.rank)+' '+cardName(c))}`:'';}).filter(Boolean).join(' → '):'逐张勾选以安排顺序；取消再勾选可移到末尾。';}
  function renderDiscard(hand,me){const need=Math.max(0,hand.length-Math.max(0,me.hp));return `<div class="action-panel"><h3>整理手牌</h3><p>需要弃掉 ${need} 张牌，使手牌不超过有效体力。</p><div class="selection-cards">${hand.map(c=>`<label class="selection-chip"><input type="checkbox" data-select-card="${esc(c.uid)}" ${S.selection.includes(c.uid)?'checked':''}>${rank(c.rank)} ${esc(cardName(c))}</label>`).join('')}</div>${btn('弃掉所选牌','discard-selected','small')}<span class="help" style="margin-left:10px">已选 <span id="selection-count">${S.selection.length}</span> 张</span></div>`;}
  async function sendGameAction(action){const room=S.room;const result=await api('act',{code:room.code,revision:room.revision,requestId:uid(),action});S.selectedCard=null;S.selectedSkill=null;S.selectedEquipment=null;S.selection=[];S.costSelection=[];S.giveSelection=[];S.costCard='';useRoom(result);}
  function download(name,value){const a=document.createElement('a');const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
  async function poll(){if(!S.code||!S.token||S.polling||S.busy||document.hidden)return;S.polling=true;try{useRoom(await api('room',{code:S.code}));}catch(error){if([403,404].includes(error.status)){S.code=null;S.room=null;writeLocal('imaginary.room',null);updateHeader();if(S.view==='room'){navigate('home');toast(error.message,true);}}else setNetwork(false,error.status===401?'身份已失效 · 请重新登记':'连接中断 · 正在重试');}finally{S.polling=false;}}
  document.addEventListener('click',event=>{const nav=event.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return;}const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;const index=Number(el.dataset.index);const id=el.dataset.id;if(handleLibraryAction(action,el,index,id))return;
    if(action==='close-modal'){$('#modal').close();return;}if(action==='noop')return;if(action==='go-home'){navigate('home');return;}if(action==='select-build'){S.selectedBuild=id;writeLocal('imaginary.build',id);renderHome();renderHistory();return;}if(action==='new-build'){editorStart(selectedBuild());return;}if(action==='create-room'){roomForm();return;}if(action==='feedback'){showModal('留下一条内测手记',`<p>记录触发步骤、预期与实际结果，或者告诉我们这局哪里最有趣。</p><label>反馈内容<textarea id="feedback-text" rows="5" maxlength="4000" placeholder="例如：第 3 回合使用…时，我预期…，但实际…"></textarea></label><p class="help">${S.room?'将关联房间 '+esc(S.room.code)+' 的服务器记录。':'反馈会关联你的本机旅人身份。'}</p>`,btn('提交反馈','submit-feedback',''));return;}
    if(action==='identity'){showModal('你的本机旅人身份',`<p>${S.user?`你当前以「${esc(S.user.name)}」参与内测。此身份的令牌保存在当前浏览器，刷新页面可继续游戏。`:'首次入局会自动建立旅人身份。你也可以先填写昵称。'}</p>${S.user?'<p class="notice warning">清除浏览器存储会失去身份。需要换设备时，可导出身份凭据并在新设备导入；凭据等同登录钥匙，请自行保管。</p>':`<label>旅人昵称<input id="guest-name" maxlength="24" placeholder="给自己起个名字" value="${esc(readLocal('imaginary.name')||'')}"></label>`}`,S.user?btn('导出身份凭据','export-identity','secondary')+btn('导入身份凭据','import-identity','secondary'):btn('导入身份凭据','import-identity','secondary')+btn('登记身份','register',''));return;}
    if(action==='load-example'){loadExamples();return;}if(action==='confirm-load'){const build=allBuilds().find(b=>b.id===$('#build-picker').value);$('#modal').close();editorStart(build);return;}if(action==='art'){S.editor.character.art=el.dataset.id||index;S.editorDirty=true;renderWorkshop();schedulePreview();return;}if(action==='add-skill'){if(S.editor.character.skills.length>=2)return;S.editor.character.skills.push({name:'新技能',trigger:'active',condition:'always',cost:{hand:1,mind:0},effects:[{op:'draw',amount:1,target:'self',color:'neutral'}],limit:1});S.editorDirty=true;renderWorkshop();schedulePreview();return;}if(action==='remove-skill'){S.editor.character.skills.splice(index,1);S.editorDirty=true;renderWorkshop();schedulePreview();return;}if(action==='add-effect'){const effects=getPath(el.dataset.path);if(effects.length<3)effects.push({op:'draw',amount:1,target:'self',color:'neutral'});S.editorDirty=true;renderWorkshop();schedulePreview();return;}if(action==='remove-effect'){getPath(el.dataset.path).splice(index,1);S.editorDirty=true;renderWorkshop();schedulePreview();return;}if(action==='move-slot'){const next=index+Number(el.dataset.direction);[S.editor.deck[index],S.editor.deck[next]]=[S.editor.deck[next],S.editor.deck[index]];S.editorDirty=true;renderWorkshop();schedulePreview();return;}if(action==='advanced'){showModal('高级构筑导入 / 导出',`<p>普通创作只需拼积木。这里可交换构筑文件；导入内容仍须通过同样的服务器校验。</p><label>构筑 JSON<textarea id="build-json" class="advanced-textarea" spellcheck="false">${esc(JSON.stringify(S.editor,null,2))}</textarea></label><label style="margin-top:12px">也可以选择文件<input id="build-file" type="file" accept=".json,application/json"></label>`,(S.editor.id?btn('删除已保存构筑','delete-build','danger small'):'')+btn('下载构筑文件','download-build','secondary')+btn('校验并导入','import-build',''));return;}
    if(action==='delete-build'){showModal('删除这份已保存构筑',`<p>将从你的构筑收藏中删除「${esc(S.editor.name)}」。已开始的对局保留当时的构筑快照。</p><p class="help">如需留档，请先返回导入 / 导出窗口下载构筑文件。</p>`,btn('取消','close-modal','secondary')+btn('确认删除','confirm-delete-build','danger'));return;}if(action==='download-build'){download((S.editor.name||'心象构筑')+'.json',S.editor);return;}if(action==='select-card'){S.costSelection=[];S.giveSelection=[];S.costCard='';S.selectedCard=S.selectedCard===id?null:id;S.selectedSkill=null;S.selectedEquipment=null;renderGame();return;}if(action==='select-skill'){S.costSelection=[];S.giveSelection=[];S.costCard='';S.selectedSkill=S.selectedSkill===index?null:index;S.selectedCard=null;S.selectedEquipment=null;renderGame();return;}if(action==='select-equipment'){S.selectedEquipment=S.selectedEquipment===id?null:id;S.selectedCard=null;S.selectedSkill=null;renderGame();return;}if(action==='clear-card'){S.selectedCard=null;S.selectedSkill=null;S.selectedEquipment=null;renderGame();return;}if(action==='target'){S.selectedTarget=S.selectedTarget===id?'':id;renderGame();return;}if(action==='clear-target'){S.selectedTarget='';renderGame();return;}if(action==='copy-code'){const code=S.room.code;if(navigator.clipboard)navigator.clipboard.writeText(code).then(()=>toast('房间码已复制：'+code)).catch(()=>toast('房间码：'+code));else toast('房间码：'+code);return;}if(action==='export-identity'){download('心象实验室-身份凭据-请勿分享.json',{format:'imaginary-identity-v1',token:S.token,name:S.user.name});return;}if(action==='import-identity'){showModal('在这台设备恢复旅人身份',`<p>请选择你之前导出的身份凭据。导入会切换当前设备使用的身份。</p><label>身份文件<input id="identity-file" type="file" accept=".json,application/json"></label>`,btn('验证并恢复身份','confirm-import-identity',''));return;}
    run(async()=>{if(action==='practice')await createRoom(true);else if(action==='confirm-create')await createRoom(false);else if(action==='join-room'){const code=$('#join-code').value.trim().toUpperCase();if(!/^[A-Z0-9]{6}$/.test(code))throw new Error('请输入 6 位字母或数字房间码。');await ensureSession();useRoom(await api('join_room',{code,...buildPayload(selectedBuild().id)}));navigate('room');}else if(action==='register'){await ensureSession();$('#modal').close();render();toast('身份已登记，欢迎入局。');}else if(action==='choose-build'){const pick=$('#build-picker').value;useRoom(await api('choose_build',{code:S.code,...buildPayload(pick)}));S.selectedBuild=pick;writeLocal('imaginary.build',pick);toast('出战构筑已切换。');}else if(action==='add-bot')useRoom(await api('add_bot',{code:S.code}));else if(action==='start-game')useRoom(await api('start',{code:S.code}));else if(action==='leave-room'){await api('leave_room',{code:S.code});S.rooms=S.rooms.filter(r=>r.code!==S.code);S.room=null;S.code=null;writeLocal('imaginary.room',null);navigate('home');}else if(action==='confirm-delete-build'){const deletedId=S.editor.id;await api('delete_build',{id:deletedId});await refreshMe();if(S.selectedBuild===deletedId){S.selectedBuild=allBuilds()[0].id;writeLocal('imaginary.build',S.selectedBuild);}S.editor=null;S.editorDirty=false;$('#modal').close();navigate('home');toast('构筑已从收藏中删除。');}else if(action==='save-build')await saveBuild();else if(action==='submit-feedback'){const text=$('#feedback-text').value.trim();if(text.length<5)throw new Error('请写下至少 5 个字的反馈。');await ensureSession();await api('feedback',{code:S.room?.code,text});$('#modal').close();toast('手记已记录，感谢一起完善规则。');}else if(action==='legal'){const candidate=legal()[index];if(candidate){const a=clone(candidate.action);if(a.costCard&&S.costCard)a.costCard=S.costCard;if(a.type==='skill'&&S.costSelection.length)a.costCards=S.costSelection;if(a.type==='skill'&&S.giveSelection.length)a.selection=S.giveSelection;await sendGameAction(a);}}else if(action==='reconnect-room'){useRoom(await api('room',{code:id}));navigate('room');}else if(action==='discard-selected')await sendGameAction({type:'discard',cards:S.selection});else if(action==='pending-selection'){const candidate=legal().find(l=>l.action?.type==='respond'&&(l.action.cards||l.action.selection));if(!candidate)throw new Error('当前选择请使用上方对应响应按钮。');const a=clone(candidate.action);if(a.cards)a.cards=S.selection;else a.selection=S.selection;await sendGameAction(a);}else if(action==='export-game'){download('时空并错-'+S.code+'-复盘.json',await api('export',{code:S.code}));toast('对局记录已导出。');}else if(action==='import-build'){const raw=JSON.parse($('#build-json').value);if(!raw||typeof raw!=='object'||Array.isArray(raw))throw new Error('构筑 JSON 的最外层必须是一个对象。');if(raw.id)delete raw.id;await ensureSession();const validated=await api('validate_build',{build:raw});$('#modal').close();editorStart(validated.build);S.budget=validated.budget;S.editorDirty=true;renderWorkshop();toast('构筑已载入；保存后可用于游戏。');}else if(action==='confirm-import-identity'){const file=$('#identity-file').files[0];if(!file||file.size>16384)throw new Error('请选择有效的身份文件。');const data=JSON.parse(await file.text());if(data.format!=='imaginary-identity-v1'||typeof data.token!=='string')throw new Error('身份文件格式不正确。');const previous=S.token,previousUser=S.user;S.token=data.token;try{await refreshMe({keepAuth:true});}catch(error){S.token=previous;S.user=previousUser;updateHeader();throw error;}writeLocal('imaginary.token',S.token);writeLocal('imaginary.name',S.user.name);S.room=null;S.code=null;writeLocal('imaginary.room',null);$('#modal').close();navigate('home');toast('已恢复 '+S.user.name+' 的身份。');}});
  });
  document.addEventListener('change',async event=>{const el=event.target;if(el.dataset.field)editorChange(el);if(el.id==='library-series'){S.librarySeries=el.value;S.libraryPage=0;renderLibraryResults();}if(el.id==='puzzle-series'){S.puzzle.series=el.value;renderPuzzleResults();}if(el.id==='puzzle-scope'){S.puzzle.scope=el.value;renderPuzzleResults();}if(el.id==='puzzle-file'){const file=el.files[0];if(file){if(file.size>500000){toast('拼图文件不能超过 500 KB。',true);return;}$('#puzzle-json').value=await file.text();}}if(el.id==='action-cost-card')S.costCard=el.value;if(el.dataset.giveCard){const id=el.dataset.giveCard;if(el.checked&&!S.giveSelection.includes(id))S.giveSelection.push(id);else if(!el.checked)S.giveSelection=S.giveSelection.filter(v=>v!==id);}if(el.dataset.costCard){const id=el.dataset.costCard;if(el.checked&&!S.costSelection.includes(id))S.costSelection.push(id);else if(!el.checked)S.costSelection=S.costSelection.filter(v=>v!==id);}if(el.id==='action-target'){S.selectedTarget=el.value;renderGame();}if(el.dataset.selectCard){const id=el.dataset.selectCard;if(el.checked&&!S.selection.includes(id))S.selection.push(id);else if(!el.checked)S.selection=S.selection.filter(v=>v!==id);$('#selection-count')&&($('#selection-count').textContent=S.selection.length);if($('#selection-order'))$('#selection-order').innerHTML=selectionOrder(S.room.game.pending.cards);}if(el.id==='build-file'){const file=el.files[0];if(!file)return;if(file.size>128000){toast('构筑文件不能超过 128 KB。',true);return;}$('#build-json').value=await file.text();}});
  document.addEventListener('input',event=>{const el=event.target;if(el.dataset.field&&el.tagName==='INPUT')editorChange(el);if(el.id==='library-search'){S.libraryQuery=el.value;S.libraryPage=0;renderLibraryResults();}if(el.id==='puzzle-search'){S.puzzle.query=el.value;renderPuzzleResults();}if(el.id==='art-search')renderArtResults(el.value);if(el.id==='card-search'){S.cardFilter=el.value;$('#reference-results').innerHTML=referenceCards();}});
  document.addEventListener('keydown',event=>{const el=event.target;if((event.key==='Enter'||event.key===' ')&&el.matches('article[data-action]')){event.preventDefault();el.click();}if(event.key==='Enter'&&el.id==='join-code')$('[data-action="join-room"]').click();});
  window.addEventListener('beforeunload',event=>{if(S.editorDirty){event.preventDefault();event.returnValue='';}});
  window.addEventListener('online',poll);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});
  window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(['home','workshop','library','reference','room'].includes(view)&&view!==S.view)navigate(view==='room'&&!S.room?'home':view);});
  async function init(){try{S.catalog=await api('catalog');loadLocalTemplates();if(S.token){try{await refreshMe();}catch(error){toast('本机身份无法恢复，请重新登记或导入身份凭据。',true);}}if(S.code&&S.token){try{useRoom(await api('room',{code:S.code}));}catch(error){if([403,404].includes(error.status)){S.code=null;writeLocal('imaginary.room',null);}}}const hash=location.hash.slice(1);navigate(S.room?'room':(['home','workshop','library','reference'].includes(hash)?hash:'home'));setInterval(poll,2000);setInterval(updateDeadline,1000);}catch(error){$('#main').innerHTML=`<section class="panel" style="margin:50px auto;max-width:600px"><span class="eyebrow">CONNECTION REQUIRED</span><h1>实验室暂时无法连接。</h1><p>${esc(error.message)}</p><p class="help">请确认此目录通过 PHP 网站服务访问，并已经安装 PDO SQLite 或 MySQL 扩展。直接双击 HTML 文件无法启动游戏服务。</p><button class="btn" onclick="location.reload()">重新连接 ↻</button></section>`;}}
  init();
})();
